import json, re

unified_answers = {
    # Exam (1-25)
    "ws_ch1_1_w1": "يقوم قانون مور على ملاحظة تجريبية مفادها أن عدد الترانزستورات على شريحة الدائرة المتكاملة يتضاعف تقريباً كل عامين مع انخفاض التكلفة والحجم وتضاعف القدرة الحسابية، وهو ما ساهم تاريخياً في نقل الحواسيب من غرف عملاقة ومحتكرة إلى حواسيب شخصية وهواتف ذكية في متناول الجميع مما أطلق ثورة المعلومات ومعالجة البيانات الضخمة؛ إلا أن استمرار هذا القانون يواجه اليوم تحديات فيزيائية قاهرة مع وصول الترانزستورات لأبعاد ذرية نانومترية، أبرزها انبعاث حرارة هائلة يصعب تبديدها تقليدياً وحدوث ظاهرة النفق الكمي التي تتسبب في تسرب الإلكترونات عبر الحواجز العازلة وفقدان الترانزستور لقدرته على التحكم كمفتاح ثنائي.",
    "ws_ch1_1_w2": "لا يمكن للمركبات ذاتية القيادة الاعتماد حصرياً على الحوسبة السحابية بسبب زمن التأخير الشبكي الذي يستغرقه إرسال البيانات وانتظار القرار وهو ما قد يسبب حوادث مميتة على السرعات العالية، بالإضافة إلى مخاطر انقطاع الاتصال في الأنفاق والمناطق النائية؛ وهنا يأتي دور الحوسبة الطرفية التي تعالج بيانات الكاميرات والمستشعرات لحظياً وفورياً على معالجات داخل السيارة نفسها في أجزاء من الثانية، مما يتيح اتخاذ قرارات الكبح الطارئ وتفادي العوائق باستقلالية تامة ودون الحاجة لأي اتصال بالإنترنت.",
    "ws_ch1_1_w3": "الواقع المعزز يضيف عناصر وبيانات رقمية ثلاثية الأبعاد فوق البيئة الحقيقية للمستخدم دون عزله عنها، مما يسمح له برؤية محيطه والتفاعل معه مثل قيام الجراح بعرض مسار الأوعية الدموية ثلاثياً فوق جسد المريض أثناء الجراحة أو إظهار بيانات الملاحة على زجاج السيارة، بينما الواقع الافتراضي يعزل المستخدم تماماً عن العالم الحقيقي ويغمره بالكامل في بيئة رقمية محاكاة عبر نظارات مغلقة فلا يتفاعل إلا مع محتواها المصطنع، مثل تدريب رواد الفضاء والطيارين على محاكاة رحلات ومناورات خطرة دون أي مجازفة في الواقع.",
    "ws_ch1_1_w4": "البت التقليدي وحدة بيانات ثنائية لا يمكن أن تكون إلا صفراً أو واحداً في أي لحظة، بينما الكيوبت الكمومي يمتلك بفضل قوانين ميكانيكا الكم القدرة على التواجد في حالة تراكب تمثل الصفر والواحد معاً في نفس اللحظة، وتمنح هذه الخاصية الحواسيب الكمومية قدرة حسابية خارقة لأنها تستطيع معالجة كافة الاحتمالات الممكنة بالتوازي في وقت واحد بدلاً من فحصها تتابعياً، مما يتيح لها حل مسائل التشفير والنمذجة المعقدة في ثوانٍ معدودة بعد أن كانت تتطلب آلاف السنين على أقوى الحواسيب الكلاسيكية.",
    "ws_ch1_1_w5": "ساهم ظهور الحواسيب الشخصية في السبعينيات والثمانينيات في نقل القدرة الحاسوبية وإدارة البيانات من المؤسسات الكبرى والمراكز العسكرية إلى المنازل والمكاتب، مما مكن الأفراد من زيادة إنتاجيتهم والاعتماد على أنفسهم، ثم جاء انتشار الإنترنت والويب في التسعينيات ليزيل كافة الحواجز الجغرافية ويسمح لأي إنسان بنشر المعرفة والوصول إليها لحظياً، مما أحدث ديمقراطية حقيقية للمعلومات وأرسى قواعد اقتصاد المعرفة والتجارة الإلكترونية والتواصل العالمي.",
    "ws_ch1_1_w6": "تقترب الرقائق الدقيقة من حدودها الفيزيائية نظراً لأن تكديس مليارات الترانزستورات في مساحات مليمترية دقيقة يولد حرارة هائلة جداً يستحيل تبريدها بالطرق المعتادة مما يهدد بتلف الشريحة، فضلاً عن أنه مع تصغير العوازل إلى بضعة نانومترات تبدأ ظاهرة النفق الكمي في الحدوث حيث تتسلل الإلكترونات وتتسرب عبر الحواجز الذرية العازلة وتفقد الترانزستورات قدرتها على العمل كمفاتيح تحكم ثنائية، مما يدفع الصناعة نحو المعالجات متعددة الأنوية وبدائل الحوسبة الكمومية.",
    "ws_ch1_2_w1": "تعتمد البرمجة التقليدية على تزويد الحاسوب بالبيانات والقواعد المبرمجة مسبقاً بشكل صريح لينفذها خطوة بخطوة ويصل إلى الحل، وتتصف بالجمود التام لعدم قدرتها على معالجة أي حالة جديدة لم يبرمجها الإنسان، بينما يتلقى تعلم الآلة البيانات والأمثلة الصحيحة ليتعلم ويستنبط القواعد والعلاقات الإحصائية بنفسه ويبني نموذجاً ذكياً، مما يمنحه مرونة فائقة وقدرة على التكيف والتعميم للتنبؤ بحالات وبيانات جديدة لم يرها من قبل.",
    "ws_ch1_2_w2": "تتكون الشبكة العصبية الاصطناعية من طبقة إدخال تستقبل البيانات الخام كبكسلات الصور دون معالجة، وطبقات خفية متعددة تمثل قلب الشبكة وتستخرج الأنماط والسمات المعقدة تدريجياً، وطبقة إخراج تنتج التصنيف أو القرار النهائي، بينما تمثل الأوزان معاملات عددية تحدد قوة وتأثير الاتصال بين الخلايا العصبية؛ وتتمثل عملية التعلم في قيام الشبكة بتعديل هذه الأوزان تدريجياً عند كل خطأ حتى تقلل الفارق بين تنبؤها والحل الصحيح فتصل إلى أعلى دقة ممكنة.",
    "ws_ch1_2_w3": "تحدث هلوسة الذكاء الاصطناعي لأن النماذج التوليدية مبنية رياضياً على التنبؤ الاحتمالي بالكلمة الأكثر ملاءمة للسياق دون امتلاك وعي أو فهم حقيقي للحقائق، مما قد يجعلها تختلق معلومات مغلوطة بصياغة لغوية مقنعة جداً، وتكمن خطورتها في المجالات الطبية والقانونية في أنها قد تقترح أدوية خطيرة تؤذي المرضى أو تستشهد بقضايا وقوانين وهمية تضلل العدالة؛ ويمكن الحد من مخاطرها بفرض مراجعة وتدقيق بشري إلزامي من المتخصصين قبل اعتماد المخرجات، مع ربط النماذج بمصادر وقواعد بيانات موثوقة للتحقق من صحة الوقائع.",
    "ws_ch1_2_w4": "يتفوق التعلم العميق على تعلم الآلة الكلاسيكي في التعامل مع البيانات غير المهيكلة كالصور والأصوات لأنه يستخرج الخصائص والسمات المعقدة وتدرجات الأنسجة ذاتياً عبر طبقاته المتعددة دون الحاجة لتدخل بشري يستخرجها يدوياً كما يتطلب التعلم التقليدي، بالإضافة إلى أن دقة التعلم العميق تواصل التصاعد والتحسن المستمر كلما زادت كميات البيانات والمسوحات الضخمة بدلاً من التوقف عند سقف معين من الدقة، مما يجعله قادراً على كشف أدق الأورام والتفاصيل النسيجية الخفية.",
    "ws_ch1_2_w6": "تعلم الآلة هو المظلة التي تضم خوارزميات إحصائية تتعلم الأنماط من البيانات للتصنيف والتنبؤ دون برمجة يدوية مثل مرشحات الرسائل المزعجة في البريد، بينما التعلم العميق فرع منه يعتمد على شبكات عصبية متعددة الطبقات لمعالجة البيانات المعقدة غير المهيكلة مثل أنظمة التعرف على الوجوه، أما الذكاء الاصطناعي التوليدي فهو تطور مبني على التعلم العميق يهدف إلى ابتكار وتوليد محتوى جديد تماماً من نصوص أو صور أو أكواد تحاكي الإبداع البشري مثل نموذج ChatGPT لتوليد النصوص وDALL-E لتوليد الصور.",
    "ws_ch1_2_w7": "يمثل طابع الصندوق الأسود معضلة أخلاقية وقانونية لأن الشبكات العصبية العميقة تعتمد على ملايين الحسابات المعقدة التي يستحيل على البشر فهم مسارها، مما يحرم المواطن من حقه في معرفة الأسباب المنطقية لرفض طلبه للقرض أو صدور حكم قضائي ضده، وهو ما يقوض مبدأ الشفافية والعدالة، كما يؤدي ذلك لصعوبة اكتشاف وتتبع التحيزات الخفية أو التمييز ضد فئات معينة داخل النموذج، مما يفرض ضرورة التوجه لنماذج الذكاء الاصطناعي القابلة للتفسير لضمان تبرير كل قرار بشكل واضح.",
    "ws_ch1_3_w1": "تعتمد الصيانة التنبؤية على تثبيت مستشعرات إنترنت الأشياء مثل مستشعرات الحرارة والاهتزاز والضغط على المعدات لمراقبة أدائها، حيث يحلل نموذج تعلم الآلة هذه البيانات باستمرار لرصد أي انحرافات مبكرة تنبئ بحدوث عطل ميكانيكي قبل وقوعه، مما يحقق فوائد اقتصادية كبرى تتمثل في منع التوقف المفاجئ لخطوط الإنتاج الذي يكلف المصانع خسائر مالية فادحة، وتفادي استبدال القطع السليمة دون داعٍ مع إطالة العمر الافتراضي للآلات مقارنة بأساليب الصيانة الدورية المعتادة.",
    "ws_ch1_3_w2": "تعمل أنظمة التوصية من خلال تتبع وتحليل سجل تفاعلات المستخدم وسلوكياته مثل مشترياته السابقة والمحتوى الذي يشاهده أو يقضي وقتاً أطول في تصفحه لبناء ملف لاهتماماته الشخصية، ثم توظف تقنية الترشيح التشاركي للبحث عن مستخدمين آخرين يتشابهون معه في هذه السلوكيات والأذواق؛ وبناءً على ذلك تقترح له المنتجات أو الأفلام التي حازت على إعجاب هؤلاء الشبيهين ولم يشاهدها هو بعد، مما يرفع من مبيعات المنصة وتفاعل المستخدمين لثقتهم في دقة الاقتراحات ومطابقتها لرغباتهم.",
    "ws_ch1_3_w3": "تساعد رؤية الحاسوب أطباء الأشعة بفحص صور الرنين والمقطعية بكسلاً ببكسل لاكتشاف التغيرات النسيجية والتكلسات المبكرة بدقة متناهية، ومع ذلك فهي لا تحل محل الطبيب بل تعزز دقته فقط لأن الذكاء الاصطناعي يحلل صورة منعزلة بينما الطبيب يربط النتيجة بالحالة السريرية الشاملة وتاريخ المريض المرضي وفحوصاته المعملية، فضلاً عن المسؤولية القانونية والأخلاقية؛ فالخوارزمية لا يمكن محاسبتها عند وقوع خطأ تشخيصي، ويظل الطبيب البشري وحده هو صاحب القرار المسؤول أمام القانون والمريض.",
    "ws_ch1_3_w4": "تسهم الزراعة الدقيقة في إحداث ثورة زراعية باستخدام طائرات الدرونز المزودة بكاميرات متعددة الأطياف لمسح الحقول ورصد حالة المحاصيل ورطوبة التربة وبؤر الآفات عبر نماذج الرؤية الحاسوبية، مما يحقق أثراً بيئياً ممتازاً يتمثل في توجيه مياه الري آلياً وبدقة للمساحات الجافة فقط بدلاً من الغمر العشوائي وتوفير كميات هائلة من المياه، مع رش المبيدات الكيميائية بشكل موضعي على النباتات المصابة حصراً مما يمنع تلوث المياه الجوفية ويقلل تراكم السموم في الغذاء.",
    "ws_ch1_3_w5": "الذكاء الاصطناعي الضيق هو نظام مبرمج لأداء مهمة محددة ومحصورة بكفاءة عالية دون امتلاك وعي أو تفكير عام، وتندرج تحته جميع النظم الحالية لأن البشر لم يتوصلوا بعد إلى الذكاء الاصطناعي العام القادر على محاكاة المرونة البشرية ونقل خبراته بين مجالات مختلفة، ومن أمثلته برنامج الشطرنج الذي يهزم أبطال العالم لكنه يعجز عن قراءة نص بسيط أو فهمه، وتقنية التعرف على الوجوه التي تفتح الهاتف بدقة متناهية لكنها تعجز عن تشخيص مرض جلدي أو إجراء عملية حسابية بسيطة.",
    "ws_ch1_3_w6": "يكتشف الذكاء الاصطناعي الاحتيال المالي لحظياً بمقارنة تفاصيل كل معاملة مصرفية جديدة بالسلوك المعتاد للعميل في أجزاء من الثانية وحظرها فوراً إذا أظهرت خطورة غير مألوفة، ومن أبرز المؤشرات السلوكية التي يتتبعها التناقض الجغرافي والزمني مثل استخدام البطاقة في مدينة ثم محاولة الشراء بها في دولة أخرى بعد دقائق وهو أمر مستحيل عملياً، والنمط المالي غير المعتاد كقيام حساب تعود على مشتريات صغيرة بإجراء محاولات سحب مبالغ ضخمة متتالية في ساعات متأخرة من الليل.",
    "ws_ch1_4_w1": "يتسلل التحيز الخوارزمي إلى أنظمة الذكاء الاصطناعي نتيجة استخدام بيانات تدريب تاريخية تعكس تمييزاً مجتمعياً سابقاً مثل قلة توظيف فئات معينة تاريخياً فيتعلم النموذج هذا التمييز كقاعدة صحيحة، أو بسبب ضعف تمثيل أقليات معينة في العينات مما يجعل أخطاء النظام تجاههم مرتفعة؛ ويمكن للمطورين معالجة ذلك بتدقيق وتنويع بيانات التدريب لتمثيل كافة الفئات بعدالة، واستخدام مقاييس رياضية لاختبار عدالة المخرجات بين المجموعات المختلفة، مع إشراك فرق عمل متنوعة وفرض مراجعة بشرية مستمرة للقرارات الحساسة.",
    "ws_ch1_4_w2": "تقع المسؤولية القانونية والأخلاقية في حوادث السيارات ذاتية القيادة بالأساس على الشركة المصنعة ومطوري البرمجيات في إطار مسؤولية المنتج إذا كان الحادث ناجماً عن خطأ في برمجة خوارزميات الاستشعار وتفادي العوائق، بينما يتحمل المالك أو السائق البشري المسؤولية إذا أهمل صيانة السيارة وتحديثاتها أو تجاهل تنبيهات النظام لاستلام عجلة القيادة وانشغل بالنوم أو هاتفه المحمول؛ وتتجه القوانين الحديثة إلى تحميل الشركات وشركات التأمين المسؤولية عن القيادة الذاتية الكاملة ما لم يثبت إهمال متعمد من السائق.",
    "ws_ch1_4_w3": "يوفر نشر أنظمة التعرف على الوجه فوائد أمنية مهمة كسرعة ضبط المجرمين وتعقب المفقودين وتأمين المرافق الحيوية، لكنه في المقابل يثير مخاوف شديدة لانتهاكه الخصوصية وتحويل المدن إلى مراقبة جماعية تسلب الأفراد حقهم في إخفاء الهوية في الفضاء العام وتقيد حريتهم في التجمع السلمي خوفاً من الملاحقة، إلى جانب خطر توقيف أبرياء نتيجة نسب الخطأ الخوارزمي، وهو ما يفرض وضع ضوابط قانونية مشددة تحصر استخدامها في الحالات القضائية الخطيرة بدلاً من المراقبة العشوائية المستمرة.",
    "ws_ch1_4_w4": "يُقصد بالذكاء الاصطناعي القابل للتفسير استخدام تقنيات تجعل قرارات ونماذج التعلم الآلي واضحة ومفهومة ومنطقية للبشر بدلاً من كونها صناديق سوداء مبهمة، ويعد ذلك ضرورة أخلاقية ملحة في الصحة لأن الطبيب لا يمكنه إعطاء علاج خطير لمريض دون معرفة الدليل الطبي للقرار، وفي القضاء لضمان حق المتهم في محاكمة عادلة ومعرفة حيثيات تقييم خطورته، وفي البنوك لمنح العميل مبرراً مالياً صريحاً عند رفض طلبه للقرض والتأكد من خلو القرار من أي تمييز مجحف.",
    "ws_ch1_4_w5": "تُنشأ مقاطع التزييف العميق باستخدام شبكات التعلم العميق التوليدية التي تتدرب على آلاف الصور والتسجيلات لشخص معين لتركيب ملامح وجهه ونبرة صوته بدقة فائقة على شخص آخر في فيديو مصطنع، وتشكل خطراً جسيماً على الديمقراطية من خلال فبركة تصريحات للقادة والساسة لتضليل الناخبين وإثارة الفتن، وتهدد الأمن الشخصي بابتزاز الأفراد ونشر محتويات خادشة تدمر سمعتهم؛ ويمكن مواجهتها بالاعتماد على خوارزميات الفحص الرقمي التي تكشف تباين وميض العين وتنافر الصوت مع حركة الشفاه، وسن قوانين تجرم إنشاء ونشر هذا المحتوى وتوعية المجتمع بعدم تداوله.",
    "ws_ch1_4_w6": "تتمثل الوظائف المعرضة للاندثار في الأعمال الروتينية المتكررة القائمة على قواعد نمطية محددة مثل إدخال البيانات والمحاسبة البسيطة وخدمة العملاء التقليدية وعمال التجميع في المصانع، بينما تقاوم الأتمتة الوظائف التي تتطلب إبداعاً معقداً وذكاءً عاطفياً وتواصلاً إنسانياً وتفكيراً نقدياً كالأطباء والجراحين والمعلمين والأخصائيين الاجتماعيين؛ وتستطيع الحكومات دعم المتضررين بإطلاق برامج تدريب مجانية لإعادة تأهيل العمال وإكسابهم مهارات الاقتصاد الرقمي، مع توفير شبكات أمان مالي وإعانات وظيفية مؤقتة تضمن لهم حياة كريمة أثناء فترة الانتقال الوظيفي.",
    "ws_ch1_4_w8": "يقوم الميثاق الأخلاقي على أربعة أركان أساسية هي العدالة بعدم التمييز وفحص البيانات لمنع أي تحيز فئوي، والخصوصية وحماية البيانات بالحصول على موافقة الأفراد وتشفير معلوماتهم وحفظ سريتها، والشفافية وقابلية التفسير بتقديم شرح منطقي وواضح لكيفية صدور القرارات وتجنب الصناديق السوداء، والمساءلة والرقابة البشرية بتحديد المسؤول البشري عن كل نظام وضمان وجود مشرف قادر على مراجعة وإلغاء القرار الآلي عند حدوث أي خطأ.",

    # Workshop (26-40)
    "ws_ch1_1_w7": "أحدثت تكنولوجيا المعلومات تحولات اجتماعية كبرى؛ فالدفع غير النقدي سهل المعاملات وحماها من مخاطر السرقة والتزوير لكنه يهدد المستهلكين بالاحتيال الإلكتروني وتهميش من لا يملكون حسابات بنكية، والعمل عن بُعد وفر تكاليف ومجهود المواصلات وحقق مرونة للأسر والشركات لكنه زاد العزلة الاجتماعية وتسبب في تلاشي الفواصل بين العمل والحياة الشخصية، والتعلم عبر الإنترنت أتاح الوصول للمعرفة في أي وقت وراعى الفروق الفردية في سرعة التعلم لكنه يواجه عائق الفجوة الرقمية وضعف التفاعل الإنساني المباشر.",
    "ws_ch1_1_w8": "تتولى الحوسبة الطرفية على متن الدرون معالجة بيانات كاميرات ومستشعرات رصد العوائق الفورية والتحكم في توازن الطيران وتفادي الاصطدام لأن أي تأخير شبكي في إرسالها للسحابة سيتسبب في سقوط الطائرة فوراً، بينما تُرفع إلى الخوادم السحابية المركزية سجلات استهلاك البطارية لإجراء الصيانة التنبؤية وخرائط المدن وتتبع الشحنات الإجمالية للأسطول نظراً لأنها تتطلب سعات تخزين وتحليلات ضخمة ولا تشكل خطراً داهماً يستوجب استجابة فورية بأجزاء من الثانية.",
    "ws_ch1_1_w9": "تتفوق شبكات التواصل الاجتماعي على الإعلام التقليدي بتحويل المتلقي من مجرد مشاهد سلبي إلى صانع محتوى وناشر يشارك بفاعلية في النقاش مما يطلق حملات ومبادرات مجتمعية واسعة في دقائق، بالإضافة إلى ميزة الانتشار اللحظي والفيروسي لمقاطع الفيديو والبث المباشر من قلب الحدث دون رقابة مسبقة، وهو ما يسقط حواجز التعتيم ويوحد الرأي العام العالمي خلف القضايا الإنسانية في وقت قياسي.",
    "ws_ch1_1_w10": "يُسمى هذا الإنجاز العلمي بالتفوق الكمي (أو السيادة الكمومية)، ولا يعني ذلك استبدال الحواسيب الشخصية والهواتف الذكية لأن الأجهزة الكمومية تتطلب بيئة تشغيل معقدة وتبريداً فائقاً يقترب من الصفر المطلق وعزلاً تاماً لمنع فقدان التماسك الكمومي وهو ما يستحيل وضعه في جهاز جيبي محمول، فضلاً عن أنها مخصصة لحل معادلات احتمالية فلكية في التشفير ومحاكاة الجزيئات ولا تقدم أي فائدة إضافية للمهام اليومية للمستخدم كتصفح الإنترنت وكتابة النصوص وتشغيل الفيديو.",
    "ws_ch1_2_w5": "تعتمد البرمجة التقليدية على كتابة قواعد وقوائم كلمات مفتاحية يدوياً وتفشل بسهولة أمام الأخطاء الإملائية وتنوع اللهجات وتتطلب جهداً مستمراً لتحديثها، بينما يعتمد تعلم الآلة على تدريب نموذج ذكي على آلاف الرسائل السابقة المصنفة ليتعلم سياق الكلمات والمقصد منها تلقائياً، ويتفوق تعلم الآلة بقدرته على استيعاب اللغة الطبيعية والأخطاء التعبيرية دون الحاجة لكتابة قاعدة لكل كلمة، إلى جانب تحسنه التلقائي المستمر في الدقة مع تدفق رسائل العملاء الجديدة.",
    "ws_ch1_2_w8": "تبدأ العملية باستقبال طبقة الإدخال لبكسلات الصورة كأرقام تعبر عن درجات السطوع وتمريرها عبر الشبكة، فتقوم الطبقات الخفية الأولى بمعالجة الإشارات بضربها في الأوزان لكشف الحواف البسيطة والخطوط، ثم تجمعها الطبقات الأعمق لتشكيل هيكل الرقم وهو زاوية علوية متصلة بخط مائل، حتى تصل الإشارة لطبقة الإخراج المكونة من عشر عقد للأرقام فتعطي العقدة المخصصة للرقم سبعة أعلى نسبة احتمالية وتصدر الشبكة تصنيفها النهائي بأن الصورة تمثل الرقم سبعة.",
    "ws_ch1_2_w9": "يتمثل الخطر في احتمالية احتواء الكود على ثغرات منطقية خفية تفشل في معالجة الحالات الحرجة النادرة مثل تعطل مستشعر فجأة أو تغير مفاجئ في الضغط الجوي مما قد يهدد بانهيار الطائرة، إلى جانب خطر الهلوسة البرمجية باستدعاء دوال غير معتمدة، ويجب على فرق الهندسة حظر إدراج أي كود مولد دون تدقيق واختبار بشري دقيق من خبراء سلامة الطيران، مع إخضاعه لاختبارات التحقق الصارمة وفق المعايير الدولية المعتمدة للطيران المدني.",
    "ws_ch1_2_w10": "يشترط الفصل التام لضمان قياس قدرة النموذج على التعميم والتنبؤ الدقيق بحالات وبيانات جديدة في العالم الواقعي لم يسبق له الاطلاع عليها بدلاً من قياس مجرد حفظه؛ فإذا قمنا بتقييم النموذج على نفس بيانات تدريبه فسيقع في فخ الإفراط في المطابقة ويحقق دقة وهمية كاملة بحفظ الإجابات السابقة، ولكنه سيفشل بشكل كارثي عند مواجهة أي بيانات حقيقية جديدة أثناء التطبيق العملي.",
    "ws_ch1_3_w7": "يستخدم الذكاء التنبؤي في تحليل الفحوصات والأشعة القائمة لتوقع تدهور حالة المريض أو الكشف المبكر عن الأورام بهدف تشخيص المرض واستباق الأزمات وحساب المخاطر، بينما يستخدم الذكاء التوليدي في تصميم وابتكار تركيبات جزيئية وبروتينية جديدة كلياً لتسريع اكتشاف أدوية جديدة أو صياغة تقارير سريرية ذكية بهدف الابتكار وخلق حلول علاجية لم تكن موجودة في الطبيعة من قبل.",
    "ws_ch1_3_w8": "يعمل الذكاء الاصطناعي على تحسين سلاسل التوريد عبر إدارة متغيرين رئيسيين هما التحسين الديناميكي لمسارات النقل بإعادة توجيه السفن والشاحنات لحظياً لتفادي الاختناقات المرورية والعواصف وتوفير الوقود، والتنبؤ الدقيق بحجم الطلب لإدارة سعات التخزين وتوزيع البضائع في المستودعات القريبة قبل حلول مواسم شرائها، مما يمنع تكدس الشحنات أو نفاد المخزون ويسرع عمليات التوصيل للعملاء.",
    "ws_ch1_3_w9": "يجمع المنظم الذكي بيانات درجات الحرارة والرطوبة الداخلية والخارجية وقراءات مستشعرات الحركة لمعرفة وجود الأشخاص، ويتعلم روتين مغادرة وعودة ونوم الأسرة تلقائياً بملاحظة الأنماط المتكررة دون الحاجة لبرمجة يدوية، ليحقق وفراً في الطاقة يصل إلى ثلاثين بالمئة بخفض التبريد أو التدفئة تلقائياً في فترات غياب الأسرة وإعادة تكييف المنزل قبل وصولهم بدقائق معدودة.",
    "ws_ch1_3_w10": "تتمثل التطبيقات في منصات التعلم التكيفي التي تصمم مساراً تعليمياً مخصصاً لكل طالب وفق سرعته ونقاط ضعفه، والمساعدات الآلية لتصحيح التقييمات والاختبارات الدورية، وتعمل هذه الأدوات على دعم المعلم لا استبداله من خلال توفير ساعات التصحيح الروتينية ليتفرغ للشرح الإبداعي ورعاية الطلاب المتعثرين، مع الحفاظ على دور المعلم الإنساني والتربوي الذي يفتقر إليه الذكاء الاصطناعي كبناء القيم والتحفيز والذكاء العاطفي.",
    "ws_ch1_4_w7": "ينتهك هذا النظام مبدأ العدالة بمعاقبة المتقدمين وخفض درجاتهم بسبب لكناتهم أو توترهم الطبيعي كغير ناطقين باللغة الأم وهي عوامل لا صلة لها بكفاءتهم في متطلبات الوظيفة مما يعد تمييزاً مجحفاً، كما ينتهك الصلاحية العلمية لأن تعبيرات الوجه ونظرات العين ليست مقياساً علمياً دقيقاً للذكاء أو الأمانة وتختلف باختلاف الثقافات والمواقف النفسية، وبناء قرارات التعيين عليها ممارسة غير نزيهة تظلم الكفاءات وتضر بمصلحة العمل.",
    "ws_ch1_4_w9": "تتطلب بيانات الأطفال حماية مشددة لعدم اكتمال وعيهم وإدراكهم لمخاطر جمع بياناتهم مما يمنعهم من تقديم موافقة مستنيرة، ولحمايتهم من استغلال الخوارزميات لمعرفة نزواتهم وتوجيه إعلانات وسلوكيات استهلاكية إدمانية تضر بنموهم النفسي، فضلاً عن خطورة تسجيل بصمة رقمية دائمة قد تلاحق الطفل وتؤثر سلباً على مستقبله الدراسي والمهني، وهو ما يفرض أخذ موافقة ولي الأمر الصريحة وحظر جمع بصماتهم الحيوية.",
    "ws_ch1_4_w10": "الهدف الأسمى لأخلاقيات الذكاء الاصطناعي هو ضمان تسخير التكنولوجيا لخدمة الإنسان وحماية كرامته وتعزيز العدالة المجتمعية، وهي ليست عائقاً أمام الابتكار بل ركيزته الأساسية لأنها تبني الثقة العامة لدى المجتمع والمؤسسات التي بدونها ستواجه التطبيقات الرفض والمقاطعة والحظر القانوني، كما تدفع المطورين لبناء نظم موثوقة وخالية من الأخطاء والتحيز متوافقة مع القوانين الدولية مما يضمن استدامتها وريادتها في الأسواق."
}

with open('frontend/src/chapter1WorkshopQuestions.ts', 'r', encoding='utf-8') as f:
    code = f.read()

updated_count = 0
for qid, new_ans in unified_answers.items():
    # Replace ideal_answer_ar for this question
    pattern = r'("id":\s*"' + qid + r'"[\s\S]*?"ideal_answer_ar":\s*)"[\s\S]*?"(\s*,\s*"ideal_answer_en")'
    def repl(m):
        global updated_count
        updated_count += 1
        escaped_ans = json.dumps(new_ans, ensure_ascii=False)
        return m.group(1) + escaped_ans + m.group(2)
    
    code, count = re.subn(pattern, repl, code, count=1)

with open('frontend/src/chapter1WorkshopQuestions.ts', 'w', encoding='utf-8') as f:
    f.write(code)

print(f"Updated {updated_count} questions in chapter1WorkshopQuestions.ts")
